class Solution:
    def isPossible(self, nums: list[int]) -> bool:
        from collections import Counter, defaultdict
        if len(nums) > 18:
            left = Counter(nums)
            need = defaultdict(int)
            for x in nums:
                if left[x] == 0:
                    continue
                left[x] -= 1
                if need[x]:
                    need[x] -= 1
                    need[x + 1] += 1
                elif left[x + 1] and left[x + 2]:
                    left[x + 1] -= 1
                    left[x + 2] -= 1
                    need[x + 3] += 1
                else:
                    return False
            return True
        vals = sorted(set(nums))
        pos = {v: i for i, v in enumerate(vals)}
        start = tuple(Counter(nums)[v] for v in vals)
        memo = {}
        def dfs(counts):
            if counts in memo:
                return memo[counts]
            first = -1
            for i, c in enumerate(counts):
                if c:
                    first = i
                    break
            if first == -1:
                return True
            x = vals[first]
            cur = list(counts)
            y = x
            while y in pos and cur[pos[y]]:
                cur[pos[y]] -= 1
                if y - x + 1 >= 3 and dfs(tuple(cur)):
                    memo[counts] = True
                    return True
                y += 1
            memo[counts] = False
            return False
        return dfs(start)

solutions.better:
class Solution:
    def isPossible(self, nums: list[int]) -> bool:
        import heapq
        from collections import defaultdict
        ends = defaultdict(list)
        for x in nums:
            if ends[x - 1]:
                heapq.heappush(ends[x], heapq.heappop(ends[x - 1]) + 1)
            else:
                heapq.heappush(ends[x], 1)
        return all(not h or h[0] >= 3 for h in ends.values())

